@push('scripts')<script>
document.addEventListener('DOMContentLoaded',()=>{const modal=new bootstrap.Modal(document.getElementById('serviceOrderModal')),form=document.getElementById('serviceOrderForm'),positions=document.getElementById('orderAnimals'),saved=@json($animalsPayload),cats=@json($categoriesPayload),esc=v=>String(v||'').replaceAll('&','&amp;').replaceAll('"','&quot;'),types=['передержка','выгул','уход'];
function serviceRow(box,index,service={}){let i=box.children.length,row=document.createElement('div');row.className='animal-service-row';row.innerHTML=`<span class="animal-service-type">${service.service_type||''}</span><label class="small">Раз в день<input class="form-control" type="number" min="1" max="24" name="animals[${index}][services][${i}][units_per_day]" value="${service.units_per_day||1}"><input type="hidden" name="animals[${index}][services][${i}][service_type]" value="${service.service_type||''}"></label><label class="small">Цена за услугу, ₽<input class="form-control" type="number" min="0" name="animals[${index}][services][${i}][unit_price]" value="${service.unit_price||500}"></label><button type="button" class="btn btn-sm btn-outline-danger" title="Убрать услугу"><i class="fa fa-xmark"></i></button>`;row.querySelector('button').onclick=()=>row.remove();box.append(row)}
function animalRow(position={}){let index=positions.children.length,row=document.createElement('section');row.className='animal-editor';let animalOpts='<option value="">Выбрать сохранённого</option>'+saved.map(a=>`<option value="${a.id}" ${String(a.id)===String(position.animal_id)?'selected':''}>${esc(a.name)}${a.client?' · '+esc(a.client):''}</option>`).join(''),catOpts='<option value="">Вид</option>'+cats.map(c=>`<option value="${c.id}" ${String(c.id)===String(position.category_id)?'selected':''}>${esc(c.name)}</option>`).join('');row.innerHTML=`<div class="animal-editor__head"><strong>Питомец</strong><button type="button" class="btn btn-sm btn-outline-danger"><i class="fa fa-trash"></i> Удалить</button></div><div class="animal-editor__fields"><label class="small">Сохранённый<select class="form-select animal-select" name="animals[${index}][animal_id]">${animalOpts}</select></label><label class="small">Или новый<input class="form-control animal-name" name="animals[${index}][name]" value="${esc(position.name)}" placeholder="${esc(position.label||'Кличка')}"></label><label class="small">Вид<select class="form-select animal-category" name="animals[${index}][category_id]">${catOpts}</select></label><label class="small">Количество<input class="form-control" type="number" min="1" name="animals[${index}][quantity]" value="${position.quantity||1}"></label></div><div class="animal-editor__services"><div class="animal-service-add"><button class="btn btn-outline-primary" type="button" aria-label="Добавить услугу" title="Добавить услугу"><i class="fa fa-plus"></i></button><div class="animal-service-add__menu is-hidden">${types.map(type=>`<button type="button" data-type="${type}">${type[0].toUpperCase()+type.slice(1)}</button>`).join('')}</div></div><div class="animal-service-list"></div></div>`;row.querySelector('.animal-editor__head button').onclick=()=>row.remove();row.querySelector('.animal-select').onchange=e=>{let a=saved.find(item=>item.id==e.target.value);if(a){row.querySelector('.animal-name').value=a.name;row.querySelector('.animal-category').value=a.category_id||''}};let list=row.querySelector('.animal-service-list'),serviceAdd=row.querySelector('.animal-service-add'),serviceMenu=row.querySelector('.animal-service-add__menu');serviceAdd.querySelector('.btn').onclick=event=>{event.stopPropagation();document.querySelectorAll('.animal-service-add__menu').forEach(menu=>{if(menu!==serviceMenu)menu.classList.add('is-hidden')});serviceMenu.classList.toggle('is-hidden')};serviceMenu.addEventListener('click',event=>event.stopPropagation());serviceMenu.querySelectorAll('[data-type]').forEach(button=>button.onclick=()=>{serviceRow(list,index,{service_type:button.dataset.type,units_per_day:1,unit_price:500});serviceMenu.classList.add('is-hidden')});(position.services||[{service_type:'уход',units_per_day:1,unit_price:500}]).forEach(service=>serviceRow(list,index,service));positions.append(row)}
window.addOrderAnimalRow=animalRow;function open(data){let isEdit=Boolean(data?.id);form.action=isEdit?`{{ url('/zooadmin/service-orders') }}/${data.id}`:`{{ route('admin.service-orders.store') }}`;document.getElementById('orderMethod').value=isEdit?'PUT':'POST';document.getElementById('orderModalTitleText').textContent=isEdit?'Редактировать заказ':'Новый заказ';document.getElementById('orderModalIcon').className=isEdit?'fa fa-pen text-primary':'fa fa-plus-circle text-primary';document.getElementById('orderClient').value=data?.client_id||'';document.getElementById('orderStart').value=data?.start||'';document.getElementById('orderEnd').value=data?.end||'';document.getElementById('orderAddress').value=data?.address||'';document.getElementById('orderNote').value=data?.note||'';positions.innerHTML='';(data?.animals||[{}]).forEach(animalRow);modal.show()}document.querySelector('.js-new-service-order').onclick=()=>open();document.querySelectorAll('.js-edit-service-order').forEach(button=>button.onclick=()=>open(JSON.parse(button.dataset.order)));document.getElementById('addOrderAnimal').onclick=()=>animalRow();document.addEventListener('click',()=>document.querySelectorAll('.animal-service-add__menu').forEach(menu=>menu.classList.add('is-hidden')));});
document.addEventListener('DOMContentLoaded',()=>{const clientFields=document.getElementById('quickClientFields'),toggleClient=document.getElementById('toggleQuickClient'),closeClientFields=()=>clientFields?.classList.add('d-none');toggleClient?.addEventListener('click',event=>{event.stopPropagation();if(!clientFields)return;let opening=clientFields.classList.contains('d-none');closeClientFields();if(!opening)return;let rect=toggleClient.getBoundingClientRect();clientFields.style.top=`${rect.bottom+8}px`;clientFields.style.left=`${Math.max(16,Math.min(rect.right-300,window.innerWidth-316))}px`;clientFields.classList.remove('d-none');document.getElementById('newClientName')?.focus()});clientFields?.addEventListener('click',event=>event.stopPropagation());document.addEventListener('click',closeClientFields);window.addEventListener('resize',closeClientFields);document.querySelectorAll('.js-new-service-order,.js-edit-service-order').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[name^="new_client"]').forEach(input=>input.value='');closeClientFields()}))});
</script>@endpush
@push('scripts')<script>
document.addEventListener('DOMContentLoaded',()=>{const root=document.getElementById('orderAnimals'),base='{{ url('/zooadmin/animals') }}';if(!root)return;const refresh=row=>{const select=row.querySelector('.animal-select'),field=row.querySelector('.animal-editor__quick-actions');if(!select)return;let actions=field;if(!actions){actions=document.createElement('div');actions.className='animal-editor__quick-actions';select.closest('label').after(actions)}if(!select.value){actions.innerHTML='';return}let url=`${base}/${select.value}`;actions.innerHTML=`<a class="btn btn-sm btn-outline-secondary" href="${url}" target="_blank" rel="noopener">Просмотреть</a><a class="btn btn-sm btn-outline-primary" href="${url}/edit" target="_blank" rel="noopener">Редактировать</a>`};root.addEventListener('change',event=>{if(event.target.matches('.animal-select'))refresh(event.target.closest('.animal-editor'))});new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>{if(node.nodeType===1&&node.matches('.animal-editor'))refresh(node)}))).observe(root,{childList:true})});
</script>@endpush
@push('scripts')<script>
document.addEventListener('DOMContentLoaded',()=>{const root=document.getElementById('orderAnimals'),button=document.getElementById('addOrderAnimal'),popover=document.getElementById('addAnimalPopover'),saved=document.getElementById('addAnimalSaved'),name=document.getElementById('addAnimalName'),category=document.getElementById('addAnimalCategory'),quantity=document.getElementById('addAnimalQuantity'),confirm=document.getElementById('confirmAddAnimal'),close=()=>popover.classList.add('is-hidden');if(!root||!button||!popover)return;button.onclick=event=>{event.stopPropagation();popover.classList.toggle('is-hidden')};popover.addEventListener('click',event=>event.stopPropagation());document.addEventListener('click',close);saved.addEventListener('change',()=>{let option=saved.options[saved.selectedIndex];if(saved.value){name.value=option.dataset.name||'';category.value=option.dataset.category||''}});confirm.onclick=()=>{if(!saved.value&&!name.value.trim()){name.focus();return}let rowData={animal_id:saved.value||null,name:name.value.trim(),category_id:category.value||null,quantity:Math.max(1,Number(quantity.value)||1),services:[]};window.addOrderAnimalRow(rowData);close();saved.value='';name.value='';category.value='';quantity.value='1'};root.addEventListener('click',event=>{let remove=event.target.closest('.animal-editor__head button');if(remove&&!confirm('Удалить питомца из этого заказа?'))event.preventDefault()});new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>{if(node.nodeType!==1||!node.matches('.animal-editor'))return;let service=node.querySelector('.animal-service-add .btn');if(service)service.innerHTML='<i class="fa fa-plus"></i> Добавить услугу';let remove=node.querySelector('.animal-editor__head button');if(remove)remove.onclick=event=>{if(confirm('Удалить питомца из этого заказа?'))node.remove()}}))).observe(root,{childList:true})});
</script>@endpush
@push('scripts')<script>
document.addEventListener('DOMContentLoaded',()=>document.getElementById('serviceOrderModal')?.addEventListener('shown.bs.modal',()=>document.querySelectorAll('#orderAnimals .animal-editor').forEach(row=>{let saved=row.querySelector('.animal-select'),name=row.querySelector('.animal-name');if(!saved?.value&&!name?.value?.trim())row.remove()})));
</script>@endpush
@push('scripts')<script>
document.addEventListener('DOMContentLoaded',()=>document.getElementById('orderAnimals')?.addEventListener('click',event=>{let button=event.target.closest('.animal-editor__head button');if(!button)return;event.preventDefault();event.stopImmediatePropagation();if(window.confirm('Удалить питомца из этого заказа?'))button.closest('.animal-editor')?.remove()},true));
</script>@endpush
@push('scripts')<script>
document.addEventListener('DOMContentLoaded',()=>{const root=document.getElementById('orderAnimals');if(!root)return;const enhance=row=>{if(row.dataset.searchReady)return;let select=row.querySelector('.animal-select'),name=row.querySelector('.animal-name'),category=row.querySelector('.animal-category');if(!select||!name||!category)return;row.dataset.searchReady='1';let options=[...select.options].filter(option=>option.value).map(option=>({id:option.value,name:option.textContent.split(' · ')[0].trim()})),listId=`animal-search-${Date.now()}-${Math.random().toString(36).slice(2)}`,input=document.createElement('input'),list=document.createElement('datalist');list.id=listId;options.forEach(option=>{let item=document.createElement('option');item.value=option.name;list.append(item)});input.className='form-control animal-search';input.placeholder='Начните вводить кличку';input.setAttribute('list',listId);input.value=name.value||options.find(option=>option.id===select.value)?.name||'';select.closest('label').replaceWith(input);name.closest('label').style.display='none';category.closest('label').style.display='none';input.after(list);input.addEventListener('input',()=>{let match=options.find(option=>option.name.toLowerCase()===input.value.trim().toLowerCase());select.value=match?.id||'';name.value=match?'':input.value.trim();select.dispatchEvent(new Event('change'))})};new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>{if(node.nodeType===1&&node.matches('.animal-editor'))enhance(node)}))).observe(root,{childList:true});root.querySelectorAll('.animal-editor').forEach(enhance)});
</script>@endpush
@push('scripts')<script>
document.addEventListener('DOMContentLoaded',()=>{const root=document.getElementById('orderAnimals');if(!root)return;const refine=row=>{let input=row.querySelector('.animal-search'),category=row.querySelector('.animal-category');if(input&&!input.closest('label')){let label=document.createElement('label');label.className='small';label.textContent='Питомец';input.replaceWith(label);label.append(input)}if(category)category.closest('label').style.display='block';let actions=row.querySelector('.animal-editor__quick-actions');if(actions&&actions.dataset.compact!=='1'){actions.dataset.compact='1';let links=[...actions.querySelectorAll('a')];if(!links.length)return;actions.innerHTML=`<div class="pet-action-menu"><button type="button" class="btn btn-sm btn-outline-secondary">Действия</button><div class="pet-action-menu__popup is-hidden">${links.map(link=>`<a href="${link.href}" target="_blank" rel="noopener">${link.textContent}</a>`).join('')}</div></div>`;let button=actions.querySelector('button'),menu=actions.querySelector('.pet-action-menu__popup');button.onclick=event=>{event.stopPropagation();menu.classList.toggle('is-hidden')};menu.onclick=event=>event.stopPropagation()} };new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>{if(node.nodeType===1&&node.matches('.animal-editor'))refine(node)}))).observe(root,{childList:true});root.querySelectorAll('.animal-editor').forEach(refine);document.addEventListener('click',()=>root.querySelectorAll('.pet-action-menu__popup').forEach(menu=>menu.classList.add('is-hidden')))});
</script>@endpush
@push('scripts')<script>
document.addEventListener('DOMContentLoaded',()=>{const root=document.getElementById('orderAnimals'),modalEl=document.getElementById('petCardModal');if(!root||!modalEl)return;const modal=new bootstrap.Modal(modalEl);root.addEventListener('click',event=>{let link=event.target.closest('.pet-action-menu__popup a');if(!link)return;event.preventDefault();event.stopImmediatePropagation();document.getElementById('petCardModalTitle').textContent=link.textContent.trim()==='Редактировать'?'Редактировать питомца':'Карточка питомца';document.getElementById('petCardModalFrame').src=link.href;modal.show()},true);modalEl.addEventListener('hidden.bs.modal',()=>document.getElementById('petCardModalFrame').src='')});
</script>@endpush
